#!/usr/bin/env bash
cd "$(dirname "$0")"
PI=./bin/picture-it
run(){ id=$1; shift; ( s=$(date +%s); $PI "$@" -o gen/$id.png > logs/$id.out 2> logs/$id.err; echo "$id exit=$? $(( $(date +%s)-s ))s" | tee -a logs/times.log ) & }
L=gen
run t1-edit edit --model banana-pro -i gen/g1-desk.png -i $L/logo-github.png -i $L/logo-notion.png -i $L/logo-slack.png -i $L/logo-gdrive.png -i $L/logo-postgres.png --prompt "Turn Figure 1 into a YouTube thumbnail. Keep the laptop, desk, and 'Herdr.' screen exactly the same. Add five glowing rounded-square app tiles with dark fill and bright orange neon edges: on the left side stacked vertically the logos from Figure 2 (GitHub), Figure 3 (Notion), Figure 4 (Slack); on the right side the logos from Figure 5 (Google Drive) and Figure 6 (PostgreSQL), each tile with its product name in small white text underneath. Keep each logo's exact shape and colours. Connect every tile to the laptop with a thin glowing orange light wire that curves smoothly. At the top, the title '5 HERDR PLUGINS' in huge bold condensed white sans-serif capitals, with the word 'HERDR' in a bright green gradient. Near the top-right, a small tilted orange 'MUST TRY' sticker tag. A thin bright neon green border frame around the whole image."
run g7-kenny-v2 edit --model banana-pro --size 1280x720 -i ref/ref7.jpg -i src/anchor-1505-face.png --prompt "Create a 16:9 YouTube thumbnail photo. Figure 1 supplies ONLY the framing, composition and lighting mood; never copy its person or face. The man is the man in Figure 2: keep his face exactly, including his age and smooth skin; do not widen, round, age, average, or blend it, and do not add wrinkles or lines. Extreme close-up, his face fills the centre of the frame from forehead to chin, looking straight into the camera with a sad, intense stare and one single tear rolling down his cheek. On the left and right edges of the frame, several small glass medicine vials with dark red crimped caps and white labels printed 'PEPTIDES' float at different angles, the nearest ones strongly out of focus in the foreground. Dramatic low-key lighting, dark red and black background edges, cinematic."
wait
